function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function go(string $u):never{header('Location:'.$u);exit;}
function csrf():void{if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);exit('Solicitud vencida.');}}
function isAdmin():bool{return ($_SESSION['user']['role']??'')==='admin';}
function canView(string $module):bool{if(isAdmin())return true;$p=$_SESSION['user']['permissions']??[];if(!$p)return true;return !empty($p[$module]['view']);}
function canManageInventory():bool{if(isAdmin())return true;return !empty($_SESSION['user']['permissions']['products']['manage']);}
function syncProductStock(PDO $db,int $productId):void{$s=$db->prepare('SELECT COALESCE(SUM(quantity),0) FROM inventory_stock WHERE product_id=?');$s->execute([$productId]);$db->prepare('UPDATE products SET stock_quantity=? WHERE id=?')->execute([(float)$s->fetchColumn(),$productId]);}
function stockRow(PDO $db,int $warehouseId,int $productId,bool $lock=false):array{$sql='SELECT * FROM inventory_stock WHERE warehouse_id=? AND product_id=?'.($lock?' FOR UPDATE':'');$s=$db->prepare($sql);$s->execute([$warehouseId,$productId]);$r=$s->fetch();if(!$r){$db->prepare('INSERT INTO inventory_stock(warehouse_id,product_id,quantity,reserved_quantity,min_quantity) VALUES(?,?,0,0,0)')->execute([$warehouseId,$productId]);$s=$db->prepare($sql);$s->execute([$warehouseId,$productId]);$r=$s->fetch();}return $r;}

function top(string $title,string $active):void{$u=$_SESSION['user'];$msg=$_SESSION['msg']??null;unset($_SESSION['msg']);$current=$_GET['a']??'inventory';?>
