e-menu{display:none;border:0;background:transparent;font-size:25px;cursor:pointer}.sidebar-overlay{display:none}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px;box-shadow:0 4px 16px #00000008}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.c3{grid-column:span 3}.c4{grid-column:span 4}.c5{grid-column:span 5}.c6{grid-column:span 6}.c7{grid-column:span 7}.c8{grid-column:span 8}.c12{grid-column:span 12}label{display:block;font-weight:650;margin-bottom:6px}input,select,textarea{width:100%;padding:10px 11px;border:1px solid #cbd1d7;border-radius:8px;background:#fff;font:inherit}textarea{min-height:88px}.btn{display:inline-block;border:0;border-radius:8px;padding:10px 15px;background:var(--o);color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.btn.light{background:#edf0f3;color:var(--ink)}.actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.muted{color:var(--muted)}.flash{padding:12px 16px;background:#fff0e5;border:1px solid #ffd2b1;border-radius:9px;margin-bottom:18px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:12px;text-transform:uppercase;color:var(--muted)}.right{text-align:right}.pill{display:inline-block;padding:4px 9px;border-radius:20px;background:#edf0f3;font-size:12px}.pill.bad{background:#ffe8e8;color:var(--red)}.pill.ok{background:#e6f7ef;color:var(--green)}.kpi{font-size:26px;font-weight:800}.scroll{overflow:auto}@media(max-width:900px){.c3,.c4,.c5,.c6,.c7,.c8{grid-column:span 12}.sidebar{transform:translateX(-100%);transition:transform .2s ease}.sidebar.open{transform:translateX(0)}.app-topbar{left:0;justify-content:space-between;padding:0 18px}.mobile-menu{display:block}.wrap{margin:64px 0 0;padding:22px 18px}.sidebar-overlay{position:fixed;z-index:25;inset:0;background:#11182080}.sidebar.open+.sidebar-overlay{display:block}}
