$a=$_GET['a']??'inventory';
try{
 if($a==='save_warehouse'){if(!canManageInventory())throw new Exception('Tu perfil no permite modificar inventario.');csrf();$name=trim((string)($_POST['name']??''));$type=(string)($_POST['warehouse_type']??'otro');$project=(int)($_POST['project_id']??0)?:null;$notes=trim((string)($_POST['notes']??''));if($name==='')throw new Exception('Ingresá el nombre del depósito.');if(!in_array($type,['principal','vehiculo','obra','otro'],true))throw new Exception('Tipo de depósito inválido.');$db->prepare('INSERT INTO warehouses(name,warehouse_type,project_id,notes,active) VALUES(?,?,?,?,1)')->execute([$name,$type,$project,$notes]);$_SESSION['msg']='Depósito creado.';go('index.php?a=warehouses');}
 if($a==='update_min_stock'){if(!canManageInventory())throw new Exception('Tu perfil no permite modificar inventario.');csrf();$wid=(int)$_POST['warehouse_id'];$pid=(int)$_POST['product_id'];$min=max(0,(float)$_POST['min_quantity']);stockRow($db,$wid,$pid);$db->prepare('UPDATE inventory_stock SET min_quantity=? WHERE warehouse_id=? AND product_id=?')->execute([$min,$wid,$pid]);$_SESSION['msg']='Stock mínimo actualizado.';go('index.php?a=inventory&warehouse_id='.$wid);}
 if($a==='save_inventory_movement'){
  if(!canManageInventory())throw new Exception('Tu perfil no permite modificar inventario.');csrf();$pid=(int)($_POST['product_id']??0);$wid=(int)($_POST['warehouse_id']??0);$type=(string)($_POST['movement_type']??'');$qty=(float)($_POST['quantity']??0);if(!$pid||!$wid||$qty<0||!in_array($type,['entrada','salida','ajuste'],true))throw new Exception('Revisá producto, depósito, tipo y cantidad.');
  $db->beginTransaction();$r=stockRow($db,$wid,$pid,true);$current=(float)$r['quantity'];$reserved=(float)$r['reserved_quantity'];if($type==='ajuste'){$new=$qty;$delta=$new-$current;}else{$delta=$type==='entrada'?abs($qty):-abs($qty);$new=$current+$delta;}if($new<0)throw new Exception('No hay stock físico suficiente en ese depósito.');if($new-$reserved<0)throw new Exception('La operación afectaría stock reservado.');
  $from=$delta<0?$wid:null;$to=$delta>0?$wid:null;$db->prepare('UPDATE inventory_stock SET quantity=? WHERE warehouse_id=? AND product_id=?')->execute([$new,$wid,$pid]);$ins=$db->prepare('INSERT INTO inventory_movements(product_id,movement_date,movement_type,quantity,warehouse_from_id,warehouse_to_id,reference_type,reference,notes,user_id) VALUES(?,NOW(),?,?,?,?,?,?,?,?)');$ins->execute([$pid,$type,$delta,$from,$to,'manual',trim((string)($_POST['reference']??'')),trim((string)($_POST['notes']??'')),$_SESSION['user']['id']??null]);syncProductStock($db,$pid);$db->commit();$_SESSION['msg']='Movimiento registrado correctamente.';go('index.php?a=inventory_movements');
 }
 if($a==='save_inventory_transfer'){
  if(!canManageInventory())throw new Exception('Tu perfil no permite modificar inventario.');csrf();$pid=(int)($_POST['product_id']??0);$from=(int)($_POST['warehouse_from_id']??0);$to=(int)($_POST['warehouse_to_id']??0);$qty=(float)($_POST['quantity']??0);if(!$pid||!$from||!$to||$from===$to||$qty<=0)throw new Exception('Revisá producto, depósitos y cantidad.');$db->beginTransaction();$rf=stockRow($db,$from,$pid,true);stockRow($db,$to,$pid,true);$newFrom=(float)$rf['quantity']-$qty;if($newFrom<0||$newFrom-(float)$rf['reserved_quantity']<0)throw new Exception('No hay stock disponible suficiente en el depósito de origen.');$db->prepare('UPDATE inventory_stock SET quantity=? WHERE warehouse_id=? AND product_id=?')->execute([$newFrom,$from,$pid]);$db->prepare('UPDATE inventory_stock SET quantity=quantity+? WHERE warehouse_id=? AND product_id=?')->execute([$qty,$to,$pid]);$db->prepare("INSERT INTO inventory_movements(product_id,movement_date,movement_type,quantity,warehouse_from_id,warehouse_to_id,reference_type,reference,notes,user_id) VALUES(?,NOW(),'transferencia',?,?,?,?,?,?,?)")->execute([$pid,$qty,$from,$to,'transferencia',trim((string)($_POST['reference']??'')),trim((string)($_POST['notes']??'')),$_SESSION['user']['id']??null]);syncProductStock($db,$pid);$db->commit();$_SESSION['msg']='Transferencia realizada.';go('index.php?a=inventory_transfer');
 }
}catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$_SESSION['msg']='No se pudo guardar: '.$ex->getMessage();go($_SERVER['HTTP_REFERER']??'index.php?a=inventory');}

try{$warehouses=$db->query("SELECT w.*,p.project_number,p.name project_name FROM warehouses w LEFT JOIN projects p ON p.id=w.project_id WHERE w.active=1 ORDER BY FIELD(w.warehouse_type,'principal','vehiculo','obra','otro'),w.name")->fetchAll();$products=$db->query("SELECT p.id,p.sku,p.description,p.unit,pc.name category_name FROM products p LEFT JOIN product_categories pc ON pc.id=p.category_id WHERE p.active=1 AND p.track_stock=1 ORDER BY p.description")->fetchAll();$projects=$db->query('SELECT id,project_number,name FROM projects ORDER BY id DESC')->fetchAll();}catch(Throwable $ex){http_response_code(500);exit('Error al cargar inventario: '.e($ex->getMessage()));}

if($a==='inventory'){$wid=(int)($_GET['warehouse_id']??0);$q=trim((string)($_GET['q']??''));$onlyLow=!empty($_GET['low']);if(!$wid&&$warehouses)$wid=(int)$warehouses[0]['id'];$where=['p.active=1','p.track_stock=1'];$params=[$wid];if($q!==''){$where[]='(p.sku LIKE ? OR p.description LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}if($onlyLow)$where[]='COALESCE(s.quantity-s.reserved_quantity,0)<=COALESCE(s.min_quantity,0) AND COALESCE(s.min_quantity,0)>0';$s=$db->prepare("SELECT p.id,p.sku,p.description,p.unit,pc.name category_name,COALESCE(s.quantity,0) physical,COALESCE(s.reserved_quantity,0) reserved,COALESCE(s.quantity-s.reserved_quantity,0) available,COALESCE(s.min_quantity,0) min_quantity FROM products p LEFT JOIN product_categories pc ON pc.id=p.category_id LEFT JOIN inventory_stock s ON s.product_id=p.id AND s.warehouse_id=? WHERE ".implode(' AND ',$where).' ORDER BY p.description');$s->execute($params);$rows=$s->fetchAll();$totPhysical=array_sum(array_column($rows,'physical'));$totReserved=array_sum(array_column($rows,'reserved'));top('Stock actual','stock');?>
<div class="actions"><div style="flex:1"><span class="muted">Inventario</span><h1>Stock actual</h1><p class="muted">Stock físico, reservado y disponible por depósito.</p></div><?php if(canManageInventory()):?><a class="btn" href="?a=inventory_movements">+ Movimiento</a><?php endif;?></div><div class="grid"><div class="card c4"><span class="muted">Stock físico</span><div class="kpi"><?=number_format($totPhysical,2,',','.')?></div></div><div class="card c4"><span class="muted">Reservado</span><div class="kpi"><?=number_format($totReserved,2,',','.')?></div></div><div class="card c4"><span class="muted">Disponible</span><div class="kpi"><?=number_format($totPhysical-$totReserved,2,',','.')?></div></div></div><div class="card"><form method="get"><input type="hidden" name="a" value="inventory"><div class="grid"><p class="c4"><label>Depósito</label><select name="warehouse_id"><?php foreach($warehouses as $w):?><option value="<?=$w['id']?>" <?=$wid===(int)$w['id']?'selected':''?>><?=e($w['name'])?></option><?php endforeach;?></select></p><p class="c4"><label>Buscar</label><input name="q" value="<?=e($q)?>" placeholder="SKU o descripción"></p><p class="c4"><label>Vista</label><select name="low"><option value="0">Todos</option><option value="1" <?=$onlyLow?'selected':''?>>Solo faltantes / reposición</option></select></p></div><button class="btn light">Aplicar filtros</button></form></div><div class="card scroll"><table><tr><th>SKU</th><th>Producto</th><th class="right">Físico</th><th class="right">Reservado</th><th class="right">Disponible</th><th class="right">Mínimo</th><th>Estado</th></tr><?php foreach($rows as $r):$low=(float)$r['min_quantity']>0&&(float)$r['available']<=(float)$r['min_quantity'];?><tr><td><b><?=e($r['sku'])?></b></td><td><?=e($r['description'])?><br><small class="muted"><?=e($r['category_name']??'Sin categoría')?></small></td><td class="right"><?=number_format((float)$r['physical'],2,',','.')?></td><td class="right"><?=number_format((float)$r['reserved'],2,',','.')?></td><td class="right"><b><?=number_format((float)$r['available'],2,',','.')?></b></td><td class="right"><?php if(canManageInventory()):?><form method="post" action="?a=update_min_stock" style="display:flex;gap:6px;justify-content:flex-end"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="warehouse_id" value="<?=$wid?>"><input type="hidden" name="product_id" value="<?=$r['id']?>"><input style="width:90px" type="number" min="0" step=".001" name="min_quantity" value="<?=e($r['min_quantity'])?>"><button class="btn light">OK</button></form><?php else:?><?=number_format((float)$r['min_quantity'],2,',','.')?><?php endif;?></td><td><?=$low?'<span class="pill bad">Reponer</span>':'<span class="pill ok">OK</span>'?></td></tr><?php endforeach;?></table></div><?php bottom();exit;}

if($a==='inventory_movements'){$recent=$db->query("SELECT m.id,m.movement_date,m.movement_type,m.quantity,m.reference,m.notes,p.sku,p.description,wf.name warehouse_from,wt.name warehouse_to FROM inventory_movements m INNER JOIN products p ON p.id=m.product_id LEFT JOIN warehouses wf ON wf.id=m.warehouse_from_id LEFT JOIN warehouses wt ON wt.id=m.warehouse_to_id ORDER BY m.movement_date DESC,m.id DESC LIMIT 100")->fetchAll();top('Movimientos','movements');?>
<div class="actions"><div style="flex:1"><span class="muted">Inventario</span><h1>Movimientos</h1><p class="muted">Entradas, salidas y ajustes con historial completo.</p></div></div><div class="grid"><div class="card c5"><h2>Registrar movimiento</h2><form method="post" action="?a=save_inventory_movement"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><p><label>Producto</label><select name="product_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['sku'].' · '.$p['description'])?></option><?php endforeach;?></select></p><p><label>Depósito</label><select name="warehouse_id" required><?php foreach($warehouses as $w):?><option value="<?=$w['id']?>"><?=e($w['name'])?></option><?php endforeach;?></select></p><p><label>Tipo</label><select name="movement_type"><option value="entrada">Entrada</option><option value="salida">Salida</option><option value="ajuste">Ajuste a cantidad exacta</option></select></p><p><label>Cantidad</label><input type="number" min="0" step=".001" name="quantity" required></p><p><label>Referencia</label><input name="reference" placeholder="Compra, remito, obra, conteo…"></p><p><label>Notas</label><textarea name="notes"></textarea></p><button class="btn">Guardar movimiento</button></form></div><div class="card c7 scroll"><h2>Últimos movimientos</h2><table><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th class="right">Cant.</th><th>Origen / Destino</th><th>Referencia</th></tr><?php if(!$recent):?><tr><td colspan="6" class="muted">Todavía no hay movimientos.</td></tr><?php endif;?><?php foreach($recent as $m):?><tr><td><?=e(date('d/m/Y H:i',strtotime($m['movement_date'])))?></td><td><b><?=e($m['sku'])?></b><br><?=e($m['description'])?></td><td><span class="pill"><?=e($m['movement_type'])?></span></td><td class="right"><?=number_format((float)$m['quantity'],2,',','.')?></td><td><?=e(($m['warehouse_from']?:'—').' → '.($m['warehouse_to']?:'—'))?></td><td><?=e($m['reference']?:'—')?></td></tr><?php endforeach;?></table></div></div><?php bottom();exit;}

if($a==='warehouses'){top('Depósitos','warehouses');?><div class="actions"><div style="flex:1"><span class="muted">Inventario</span><h1>Depósitos</h1><p class="muted">Depósitos físicos, vehículos y ubicaciones asociadas a obras.</p></div></div><div class="grid"><div class="card c7 scroll"><table><tr><th>Nombre</th><th>Tipo</th><th>Proyecto</th><th>Estado</th></tr><?php foreach($warehouses as $w):?><tr><td><b><?=e($w['name'])?></b><br><small class="muted"><?=e($w['notes']??'')?></small></td><td><span class="pill"><?=e($w['warehouse_type'])?></span></td><td><?=e(!empty($w['project_number'])?($w['project_number'].' · '.$w['project_name']):'—')?></td><td><span class="pill ok">Activo</span></td></tr><?php endforeach;?></table></div><div class="card c5"><h2>Nuevo depósito</h2><form method="post" action="?a=save_warehouse"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><p><label>Nombre</label><input name="name" required placeholder="Ej.: Kangoo 1"></p><p><label>Tipo</label><select name="warehouse_type"><option value="principal">Principal</option><option value="vehiculo">Vehículo</option><option value="obra">Obra / Proyecto</option><option value="otro">Otro</option></select></p><p><label>Proyecto asociado</label><select name="project_id"><option value="">Sin proyecto</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=e($p['project_number'].' · '.$p['name'])?></option><?php endforeach;?></select></p><p><label>Notas</label><textarea name="notes"></textarea></p><button class="btn">Crear depósito</button></form></div></div><?php bottom();exit;}

if($a==='inventory_transfer'){top('Transferencias','transfer');?><div class="card"><div class="actions"><div style="flex:1"><span class="muted">Inventario</span><h1>Transferir stock</h1><p class="muted">Mover productos entre depósitos no modifica el stock total.</p></div></div><form method="post" action="?a=save_inventory_transfer"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><div class="grid"><p class="c6"><label>Producto</label><select name="product_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['sku'].' · '.$p['description'])?></option><?php endforeach;?></select></p><p class="c3"><label>Desde</label><select name="warehouse_from_id" required><?php foreach($warehouses as $w):?><option value="<?=$w['id']?>"><?=e($w['name'])?></option><?php endforeach;?></select></p><p class="c3"><label>Hacia</label><select name="warehouse_to_id" required><?php foreach($warehouses as $w):?><option value="<?=$w['id']?>"><?=e($w['name'])?></option><?php endforeach;?></select></p><p class="c3"><label>Cantidad</label><input type="number" min=".001" step=".001" name="quantity" required></p><p class="c4"><label>Referencia</label><input name="reference" placeholder="Ej.: Material para obra"></p><p class="c5"><label>Notas</label><input name="notes"></p></div><button class="btn">Transferir</button></form></div><?php bottom();exit;}

if($a==='inventory_reorder'){$rows=$db->query("SELECT s.*,p.sku,p.description,p.unit,w.name warehouse_name,(s.quantity-s.reserved_quantity) available,CASE WHEN s.min_quantity-(s.quantity-s.reserved_quantity)>0 THEN s.min_quantity-(s.quantity-s.reserved_quantity) ELSE 0 END suggested FROM inventory_stock s JOIN products p ON p.id=s.product_id JOIN warehouses w ON w.id=s.warehouse_id WHERE s.min_quantity>0 AND (s.quantity-s.reserved_quantity)<=s.min_quantity ORDER BY w.name,p.description")->fetchAll();top('Reposición','reorder');?><div class="actions"><div style="flex:1"><span class="muted">Inventario</span><h1>Reposición</h1><p class="muted">Productos que llegaron al mínimo configurado.</p></div></div><div class="card scroll"><table><tr><th>Depósito</th><th>SKU</th><th>Producto</th><th class="right">Disponible</th><th class="right">Mínimo</th><th class="right">Sugerido a comprar</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['warehouse_name'])?></td><td><b><?=e($r['sku'])?></b></td><td><?=e($r['description'])?></td><td class="right"><?=number_format((float)$r['available'],2,',','.')?></td><td class="right"><?=number_format((float)$r['min_quantity'],2,',','.')?></td><td class="right"><b><?=number_format((float)$r['suggested'],2,',','.')?></b></td></tr><?php endforeach;?></table><?php if(!$rows):?><p class="muted">No hay productos para reponer con los mínimos actuales.</p><?php endif;?></div><?php bottom();exit;}

http_response_code(404);echo 'Acción de inventario inexistente.';
